import { effectNames, portraitOf, urlsOf } from '../strip-urls';
import type { FighterArt } from '../types';
import { NAYO_CELLS } from './cells';
import { NAYO_CLIPS, NAYO_PROJECTILES } from './clips';
import { NAYO_SHEETS } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (energy, flashes, speed lines). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

const SHARED = {
  // His head and his guard, on the character select screen.
  portrait: { x: 30, y: 0, size: 56 },
  sheets: NAYO_SHEETS,
  clips: NAYO_CLIPS,
  projectiles: NAYO_PROJECTILES,
  cells: NAYO_CELLS,
};

/** Black techwear, cyan neon. */
export const NAYO: FighterArt = {
  key: 'nayo',
  urls: urlsOf(MAIN, 'main', NAYO_SHEETS),
  fx: urlsOf(MAIN_FX, 'main/fx', effectNames(NAYO_SHEETS, NAYO_CLIPS)),
  ...portraitOf(MAIN, 'main'),
  ...SHARED,
};
/** Light grey techwear, magenta neon: player 2 in a mirror match. */
export const NAYO_ALT: FighterArt = {
  key: 'nayo-alt',
  urls: urlsOf(ALT, 'alt', NAYO_SHEETS),
  fx: urlsOf(ALT_FX, 'alt/fx', effectNames(NAYO_SHEETS, NAYO_CLIPS)),
  ...portraitOf(ALT, 'alt'),
  ...SHARED,
};
